module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg  [1023:0] in;
    reg  [7:0]    sel;
    wire [3:0]    out;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .in  (in),
        .sel (sel),
        .out (out)
    );

    // 3. Stimulus & self-checking
    integer errors = 0;
    integer i;
    reg [3:0] expected_out;

    initial begin
        // Initialize inputs
        in = 1025'h0;
        sel = 8'h0;

        // Apply a randomized yet deterministic pattern across the 1024-bit bus
        // Fill the 1024-bit input with a patterned value so each 4-bit chunk is unique
        for (i = 0; i < 256; i = i + 1) begin
            in[i*4 +: 4] = i[3:0] ^ (i[7:4] & 4'hF);
        end

        #10;

        // Test a representative set of select values (e.g., 0 to 15, plus some higher ones)
        for (i = 0; i < 256; i = i + 1) begin
            sel = i[7:0];
            #5; // Wait for combinational propagation

            expected_out = in[sel*4 +: 4];

            if (out !== expected_out) begin
                $display("ERROR: sel=%0d: expected out=0x%h, got out=0x%h", sel, expected_out, out);
                errors = errors + 1;
            end
        end

        // Test some specific boundary conditions
        sel = 8'd0;
        #5;
        if (out !== in[3:0]) begin
            $display("ERROR: Boundary test sel=0 failed.");
            errors = errors + 1;
        end

        sel = 8'd255;
        #5;
        if (out !== in[1023:1020]) begin
            $display("ERROR: Boundary test sel=255 failed.");
            errors = errors + 1;
        end

        // Print final result status strictly conforming to requirements
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
```

